from __future__ import annotations
from .Items import item_data_table
import dataclasses
from typing import Any, Dict, Tuple
from BaseClasses import CollectionState
from rule_builder.rules import CanReachRegion, False_, Has, Rule, True_

@dataclasses.dataclass()
class HasCategoryRule(Rule[Any], game="Final Fantasy 12 Open World"):
    category: str
    count: int = 1

    def _instantiate(self, world):
        item_names = tuple(sorted(name for name, data in item_data_table.items() if data.category == self.category))
        return self.Resolved(
            self.category,
            item_names,
            count=self.count,
            player=world.player,
            caching_enabled=getattr(world, "rule_caching_enabled", False),
        )

    class Resolved(Rule.Resolved):
        category: str
        item_names: tuple[str, ...]
        count: int = 1

        def _evaluate(self, state: CollectionState) -> bool:
            return state.count_from_list(self.item_names, self.player) >= self.count

        def item_dependencies(self) -> dict[str, set[int]]:
            return {item_name: {id(self)} for item_name in self.item_names}

@dataclasses.dataclass()
class HasTraitRule(Rule[Any], game="Final Fantasy 12 Open World"):
    trait: str
    count: int = 1

    def _instantiate(self, world):
        item_names = tuple(sorted(name for name, data in item_data_table.items() if self.trait in data.traits))
        return self.Resolved(
            self.trait,
            item_names,
            count=self.count,
            player=world.player,
            caching_enabled=getattr(world, "rule_caching_enabled", False),
        )

    class Resolved(Rule.Resolved):
        trait: str
        item_names: tuple[str, ...]
        count: int = 1

        def _evaluate(self, state: CollectionState) -> bool:
            return state.count_from_list(self.item_names, self.player) >= self.count

        def item_dependencies(self) -> dict[str, set[int]]:
            return {item_name: {id(self)} for item_name in self.item_names}

@dataclasses.dataclass(init=False)
class AtLeastRule(Rule[Any], game="Final Fantasy 12 Open World"):
    count: int
    children: tuple[Rule[Any], ...]

    def __init__(self, count: int, *children: Rule[Any]):
        super().__init__()
        self.count = count
        self.children = children

    def _instantiate(self, world):
        resolved_children = tuple(child.resolve(world) for child in self.children)
        if self.count <= 0:
            return True_().resolve(world)
        if self.count > len(resolved_children):
            return False_().resolve(world)
        return self.Resolved(
            self.count,
            resolved_children,
            player=world.player,
            caching_enabled=getattr(world, "rule_caching_enabled", False),
        )

    class Resolved(Rule.Resolved):
        count: int
        children: tuple[Rule.Resolved, ...]

        def _evaluate(self, state: CollectionState) -> bool:
            found = 0
            for child in self.children:
                if child(state):
                    found += 1
                    if found >= self.count:
                        return True
            return False

        def item_dependencies(self) -> dict[str, set[int]]:
            deps: dict[str, set[int]] = {}
            for child in self.children:
                for item_name, rules in child.item_dependencies().items():
                    deps.setdefault(item_name, {id(self)}).update(rules)
            return deps

        def region_dependencies(self) -> dict[str, set[int]]:
            deps: dict[str, set[int]] = {}
            for child in self.children:
                for region_name, rules in child.region_dependencies().items():
                    deps.setdefault(region_name, {id(self)}).update(rules)
            return deps

        def location_dependencies(self) -> dict[str, set[int]]:
            deps: dict[str, set[int]] = {}
            for child in self.children:
                for location_name, rules in child.location_dependencies().items():
                    deps.setdefault(location_name, {id(self)}).update(rules)
            return deps

        def entrance_dependencies(self) -> dict[str, set[int]]:
            deps: dict[str, set[int]] = {}
            for child in self.children:
                for entrance_name, rules in child.entrance_dependencies().items():
                    deps.setdefault(entrance_name, {id(self)}).update(rules)
            return deps

